'use client';

// On/off switches in Settings and onboarding (Reduce motion, AI suggestions).
// Generated by the shadcn/ui CLI on Radix Switch and adapted: a 52×32 track
// whose knob springs across (v2 spec 4.4), a visible border when off so the
// state doesn't depend on a faint gray, and SwitchRow puts the label and the
// switch in one 48px row.
import * as React from 'react';
import { cn } from '@/lib/utils';
import { Switch as SwitchPrimitive } from 'radix-ui';

function Switch({ className, ...props }: React.ComponentProps<typeof SwitchPrimitive.Root>) {
  return (
    <SwitchPrimitive.Root
      data-slot="switch"
      className={cn(
        'peer inline-flex h-8 w-[52px] shrink-0 items-center rounded-full border-2 border-ink-soft bg-surface-2 transition-colors duration-(--dur-fast) data-checked:border-primary data-checked:bg-primary data-disabled:cursor-not-allowed data-disabled:opacity-50',
        className,
      )}
      {...props}
    >
      <SwitchPrimitive.Thumb
        data-slot="switch-thumb"
        className="pointer-events-none block size-6 translate-x-0.5 rounded-full bg-ink-soft transition-transform duration-(--dur-spring-snappy) ease-(--spring-snappy) data-checked:translate-x-[22px] data-checked:bg-on-primary"
      />
    </SwitchPrimitive.Root>
  );
}

function SwitchRow({
  id,
  label,
  description,
  checked,
  onCheckedChange,
}: {
  id: string;
  label: string;
  description?: string;
  checked: boolean;
  onCheckedChange: (checked: boolean) => void;
}) {
  return (
    <div className="flex min-h-12 items-center justify-between gap-4">
      <label htmlFor={id} className="flex flex-col">
        <span>{label}</span>
        {description && <span className="text-caption text-ink-soft">{description}</span>}
      </label>
      <Switch id={id} checked={checked} onCheckedChange={onCheckedChange} />
    </div>
  );
}

export { Switch, SwitchRow };
